@Service
public class QueryScheduler {

    private final JdbcTemplate jdbcTemplate;

    private final String queryFilePath = "src/main/resources/query.sql";
    private final String resultFilePath = "src/main/resources/result.txt";

    @Autowired
    public QueryScheduler(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Scheduled(cron = "0 0 * * * ?") // Run every day at midnight
    public void executeQueryAndStoreResult() {
        try {
            String query = readQueryFromFile(queryFilePath);
            List<String> results = jdbcTemplate.queryForList(query, String.class);

            storeResultsToFile(results, resultFilePath);

            System.out.println("Query executed and results stored successfully.");

        } catch (IOException e) {
            System.err.println("Error reading query file: " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Error executing query or storing results: " + e.getMessage());
        }
    }

    private String readQueryFromFile(String filePath) throws IOException {
        return new String(Files.readAllBytes(Paths.get(filePath)));
    }

    private void storeResultsToFile(List<String> results, String filePath) throws IOException {
        try (FileWriter writer = new FileWriter(filePath, true)) { // Append to file
            for (String result : results) {
                writer.write(result + "\n");
            }
        }
    }
}
